"""[.mark] V4 : les phrases d'aide des champs des fournisseurs, en français.

Le schéma d'un fournisseur vient de l'amont : la description de chaque champ est en anglais. Un champ qui a déjà
``mark_aide`` (voix-soniox, ``ecran_mark``) garde la sienne ; les autres sont dits ici, par la phrase anglaise exacte (donc
toute nouvelle phrase de l'amont est repérée par un test : elle reste en anglais, jamais en panne). Lu par
``BaseServiceConfiguration.__get_pydantic_json_schema__``.
"""

from __future__ import annotations

import re


def _cle(texte: str) -> str:
    """Seuls les caractères ASCII comptent : un caractère abîmé dans une description de l'amont ne casse pas la recherche."""
    return re.sub(r"\s+", " ", re.sub(r"[^ -~]", "", texte)).strip()


